package net.chronoflow.core.plan

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import net.chronoflow.core.model.api.ApiJson
import net.chronoflow.core.model.contracts.Language

/** The PlanUI `Localizable` catalog as a JVM table (`page_copy.json`, generated by `make strings`). */
class PageCopyTable(
    private val entries: Map<String, Map<String, Value>>,
) {
    class Value(
        val text: String?,
        val one: String?,
        val other: String?,
    )

    internal fun value(
        key: String,
        language: Language,
    ): Value? = entries[key]?.get(if (language == Language.Nl) "nl" else "en")

    companion object {
        fun load(): PageCopyTable {
            val bytes =
                checkNotNull(PageCopyTable::class.java.getResourceAsStream("/page_copy.json")) {
                    "page_copy.json is not on the classpath"
                }.use { it.readBytes() }
            return parse(bytes.decodeToString())
        }

        fun parse(json: String): PageCopyTable {
            val root =
                ApiJson.response
                    .parseToJsonElement(json)
                    .jsonObject
                    .getValue("entries")
                    .jsonObject
            return PageCopyTable(
                root.mapValues { (_, languages) ->
                    languages.jsonObject.mapValues { (_, value) -> toValue(value) }
                },
            )
        }

        private fun toValue(value: kotlinx.serialization.json.JsonElement): Value =
            if (value is JsonPrimitive) {
                Value(value.content, null, null)
            } else {
                val plural: JsonObject = value.jsonObject
                Value(null, plural["one"]?.jsonPrimitive?.contentOrNull, plural["other"]?.jsonPrimitive?.contentOrNull)
            }
    }
}

class PageCopy(
    val language: Language,
    private val table: PageCopyTable,
) {
    override fun equals(other: Any?): Boolean = other is PageCopy && other.language == language

    override fun hashCode(): Int = language.hashCode()

    /** `%@` placeholders are replaced left to right; `%%` is a percent sign. An unknown key reads as itself. */
    operator fun invoke(
        key: String,
        vararg args: String,
    ): String {
        val value = table.value(key, language)?.text ?: key
        return if (args.isEmpty()) value else substitute(value, args)
    }

    /** CLDR en and nl: `one` for exactly 1, `other` for everything else. */
    fun count(
        key: String,
        count: Int,
    ): String {
        val value = table.value(key, language)
        val form = (if (count == 1) value?.one else value?.other) ?: value?.text ?: key
        return form.replace("%lld", count.toString())
    }

    private fun substitute(
        format: String,
        args: Array<out String>,
    ): String {
        val out = StringBuilder(format.length + 16)
        var next = 0
        var index = 0
        while (index < format.length) {
            val char = format[index]
            if (char == '%' && index + 1 < format.length) {
                val following = format[index + 1]
                if (following == '@') {
                    out.append(args.getOrElse(next++) { "" })
                    index += 2
                    continue
                }
                if (following == '%') {
                    out.append('%')
                    index += 2
                    continue
                }
            }
            out.append(char)
            index++
        }
        return out.toString()
    }
}
